{
  "topic_summary": "Brief summary of what we're researching",
  "claims": [{
    "claim": "The factual statement",
    "category": "physics|biology|history|etc",
    "matched_fact_id": "uuid or null",
    "confidence": "verified|needs_source",
    "priority": "critical|important|nice_to_have",
    "suggested_search": "Research query for Google Scholar or similar"
  }],
  "research_gaps": ["Topics needing more research"],
  "recommended_sources": ["Types of sources to consult"]
